import{_ as s,a0 as p,w as o,s as l,ao as S,I as n,x as e,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"使用iSCSI Target创建集中式安全存储（一） | LCTT x X-CMD","titleTemplate":false,"description":"使用iSCSI Target创建集中式安全存储（一） | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用iSCSI Target创建集中式安全存储（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用iSCSI Target创建集中式安全存储（一） | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I","title":"使用iSCSI Target创建集中式安全存储（一）","tag":"201503","desc":""},"relativePath":"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I.md","filePath":"[post].md"}'),g={name:"201503/20141217 Create Centralized Secure Storage using iSCSI Target on RHEL or CentOS or Fedora Part -I.md"};function d(C,t,m,I,c,u){const i=p("Link");return o(),l("div",null,[t[16]||(t[16]=S(`<h1 id="使用iscsi-target创建集中式安全存储-一" tabindex="-1">使用iSCSI Target创建集中式安全存储（一） <a class="header-anchor" href="#使用iscsi-target创建集中式安全存储-一" aria-label="Permalink to “使用iSCSI Target创建集中式安全存储（一）”">​</a></h1><p><strong>iSCSI</strong> 是一种块级别的协议，用于通过TCP/IP网络共享<strong>原始存储设备</strong>，可以用已经存在的IP和以太网如网卡、交换机、路由器等通过iSCSI协议共享和访问存储。iSCSI target是一种由远程iSCSI服务器（target）提供的远程硬盘。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-iSCSI-Target-in-Linux.jpg" alt="Install iSCSI Target in Linux"></p><p><em>在Linux中安装iSCSI Target</em></p><p>我们不需要占用很大的资源就可以为客户端提供稳定的连接和性能。iSCSI服务器称为“Target（目标器）”，它提供服务器上的存储共享。iSCSI客户端称为“Initiator（发起程序）”，它访问目标器共享的存储。市场中有卖的用于大型存储服务如SAN的iSCSI适配器。</p><p><strong>我们为什么要在大型存储领域中使用iSCSI适配器</strong></p><p>以太网适配器（NIC）被设计用于在系统、服务器和存储设备如NAS间传输分组数据，它不适合在Internet中传输块级数据。</p><h3 id="iscsi-target的功能" tabindex="-1">iSCSI Target的功能 <a class="header-anchor" href="#iscsi-target的功能" aria-label="Permalink to “iSCSI Target的功能”">​</a></h3><ul><li>可以在一台机器上运行几个iSCSI 目标器</li><li>一台机器可以提供多个iSCSI 目标器用于iSCSI SAN访问</li><li>一个目标器就是一块存储，并且可以通过网络被发起程序（客户端）访问</li><li>把这些存储汇聚在一起让它们在网络中可以访问的是iSCSI LUN（逻辑单元号）</li><li>iSCSI支持在同一个会话中使用多个连接</li><li>iSCSI发起程序在网络中发现目标接着用LUN验证并登录，这样就可以本地访问远程存储。</li><li>我们可以在本地挂载的LUN上安装任何操作系统，就像我们安装我们本地的操作系统一样。</li></ul><h3 id="为什么需要iscsi" tabindex="-1">为什么需要iSCSI？ <a class="header-anchor" href="#为什么需要iscsi" aria-label="Permalink to “为什么需要iSCSI？”">​</a></h3><p>在虚拟化中，我们需要存储拥有高度的冗余性、稳定性，iSCSI以低成本的方式提供了这些特性。与使用光纤通道的SAN比起来，我们可以使用已经存在的设备比如NIC、以太网交换机等建造一个低成本的SAN。</p><p>现在我开始使用iSCSI 目标器安装并配置安全存储。本篇中，我们遵循下面的步骤：</p><ul><li>我们需要隔离一个系统来设置iSCSI Target服务器和发起程序（客户端）。</li><li>在大型存储环境中可以添加多个硬盘，但是这里我们除了基本的安装盘之外只使用了一个额外的驱动器。</li><li>这里我们只使用了2块硬盘，一个用于基本的服务器安装，另外一个用于存储（LUN），这个我们会在这个系列的第二篇描述。</li></ul><h4 id="主服务器设置" tabindex="-1">主服务器设置 <a class="header-anchor" href="#主服务器设置" aria-label="Permalink to “主服务器设置”">​</a></h4><ul><li>操作系统 – CentOS 6.5 (Final)</li><li>iSCSI 目标器 IP – 192.168.0.200</li><li>使用的端口 : TCP 860, 3260</li><li>配置文件 : /etc/tgt/targets.conf</li></ul><h3 id="安装-iscsi-target" tabindex="-1">安装 iSCSI Target <a class="header-anchor" href="#安装-iscsi-target" aria-label="Permalink to “安装 iSCSI Target”">​</a></h3><p>打开终端并使用yum命令来搜索需要在iscsi 目标器上安装的包名。</p><pre><code># yum search iscsi
</code></pre><h4 id="输出示例" tabindex="-1">输出示例 <a class="header-anchor" href="#输出示例" aria-label="Permalink to “输出示例”">​</a></h4><pre><code>========================== N/S matched: iscsi =======================
iscsi-initiator-utils.x86_64 : iSCSI daemon and utility programs
iscsi-initiator-utils-devel.x86_64 : Development files for iscsi-initiator-utils
lsscsi.x86_64 : List SCSI devices (or hosts) and associated information
scsi-target-utils.x86_64 : The SCSI target daemon and utility programs
</code></pre><p>你会的到上面的那些结果，选择<strong>Target</strong>包来安装。</p><pre><code># yum install scsi-target-utils -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Install-iSCSI-in-Linux.jpg" alt="Install iSCSI Utils"></p><p><em>安装iSCSI工具</em></p><p>列出安装的包里面的内容来了解默认的配置、服务和man页面的位置。</p><pre><code># rpm -ql scsi-target-utils.x86_64
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/List-All-ISCSI-Files.jpg" alt="List All iSCSI Files"></p><p><em>列出所有的iSCSI包里面的文件</em></p><p>让我们启动iSCSI服务，并检查服务运行的状态，iSCSI的服务名是<strong>tgtd</strong>。</p><pre><code># /etc/init.d/tgtd start
# /etc/init.d/tgtd status
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Start-iSCSI-Service.jpg" alt="Start iSCSI Service"></p><p><em>启动iSCSI服务</em></p><p>现在我们需要配置开机自动启动。</p><pre><code># chkconfig tgtd on
</code></pre><p>现在验证tgtd服务的运行级别是否配置正确。</p><pre><code># chkconfig --list tgtd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Enable-iSCSI-on-Startup.jpg" alt="Enable iSCSI on Startup"></p><p><em>开机启动iSCSI</em></p><p>现在使用<strong>tgtadm</strong>来列出在我们的服务器上已经配置了哪些目标器和LUN。</p><pre><code># tgtadm --mode target --op show
</code></pre><p><strong>tgtd</strong>已经安装并在运行了，但是上面的命令没有<strong>输出</strong>因为我们还没有在目标器上定义LUN。要查看手册，可以运行‘<strong>man</strong>‘命令。</p><pre><code># man tgtadm
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/iSCSI-Man-Pages.jpg" alt="iSCSI Man Pages"></p><p><em>iSCSI Man 页面</em></p><p>如果你的target服务器上有iptable的话，那么我们需要为iSCSI添加iptable规则。首先使用netstat命令找出iscsi target的端口号，target总是监听TCP端口3260。</p><pre><code># netstat -tulnp | grep tgtd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Find-iSCSI-Port.jpg" alt="Find iSCSI Port"></p><p><em>找出iSCSI端口</em></p><p>下面加入如下规则让iptable允许广播iSCSI 目标器发现包。</p><pre><code># iptables -A INPUT -i eth0 -p tcp --dport 860 -m state --state NEW,ESTABLISHED -j ACCEPT
# iptables -A INPUT -i eth0 -p tcp --dport 3260 -m state --state NEW,ESTABLISHED -j ACCEPT
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Open-iSCSI-Ports.jpg" alt="Open iSCSI Ports"></p><p><em>打开iSCSI端口</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Add-iSCSI-Ports-to-Iptables.jpg" alt="Add iSCSI Ports to Iptables"></p><p><em>添加iSCSI端口到iptable中</em></p><p><strong>注意</strong>： 规则可能根据你的 <strong>默认链策略</strong>而不同。接着保存iptable并重启该服务。</p><pre><code># iptables-save
# /etc/init.d/iptables restart
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Restart-iptables.jpg" alt="Restart iptables"></p><p><em>重启iptable</em></p><p>现在我们已经部署了一个目标器来共享LUN给通过TCP/IP认证的发起程序。这也适用于从小到大规模的生产环境。</p>`,59)),n("p",null,[t[1]||(t[1]=e("在我的下篇文章中，我会展示如何",-1)),r(i,{href:"http://www.tecmint.com/create-luns-using-lvm-in-iscsi-target/"},{default:a(()=>[...t[0]||(t[0]=[e("在目标器中使用LVM创建LUN",-1)])]),_:1}),t[2]||(t[2]=e("，并且如何在客户端中共享LUN，不要忘记留下有价值的评论。",-1))]),t[17]||(t[17]=n("hr",null,null,-1)),n("p",null,[t[4]||(t[4]=e("via: ",-1)),r(i,{href:"http://www.tecmint.com/create-centralized-secure-storage-using-iscsi-targetin-linux/"},{default:a(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/create-centralized-secure-storage-using-iscsi-targetin-linux/",-1)])]),_:1})]),n("p",null,[t[8]||(t[8]=e("作者：",-1)),r(i,{href:"http://www.tecmint.com/author/babinlonston/"},{default:a(()=>[...t[5]||(t[5]=[e("Babin Lonston",-1)])]),_:1}),t[9]||(t[9]=e(" 译者：",-1)),r(i,{href:"https://github.com/geekpi"},{default:a(()=>[...t[6]||(t[6]=[e("geekpi",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),r(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原创翻译，",-1)),r(i,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[e("Linux中国",-1)])]),_:1}),t[15]||(t[15]=e(" 荣誉推出",-1))])])}const f=s(g,[["render",d]]);export{h as __pageData,f as default};
